    im=Image.open(r'C:/Users/Administrator/AppData/Local/Temp/zentao-2920/canvas-h4-new.png').convert('RGB')
    w,h=im.size
    rows=[]
    for y in range(h):
        cnt=0
        for x in range(0,w,2):
